PROJECT_ROOT = Path(__file__).resolve().parent.parent


def _load_entry(spec):
    """Imports the function named "module:function".

    Args:
        spec (str or None): The name, or None.

    Returns:
        callable or None: The function; None if `spec` is None.
    """
    if not spec:
        return None
    module, func = spec.split(":")
    return getattr(__import__(module, fromlist=[func]), func)


def build_model(meta):
    """Rebuilds the model and data of a recorded run from the recipe in its metadata.

    The recipe is meta["model"], one of:
      {"entry": "module:function", "cfg": {...}}   a task's own rebuild function, called as function(cfg, meta) -> (model, data, reset)
                                                  (written by src/episode_runner.run_episode from the task's "recipe");
      {"kind": "scene", "scene": path}             a scene file relative to the project root, loaded with RobotSimulator;
      {"kind": "task", "task_cfg": {...}}          the form of older beaker recordings (built with src/task_beaker_hotplate.load_task).
    The cameras come from the recording's own meta["robot_specs"]["CAMERA_SPECS"].

    Args:
        meta (dict): The recording's metadata (the "meta" entry of src/run_record.load_recording).

    Returns:
        tuple: (model, data, reset), where model (mujoco.MjModel) and data (mujoco.MjData) are the rebuilt model and its data, and
        reset (callable) takes (model, data) and repeats what the live run did to data before run_loop: for an "entry" or
        "task" recipe it resets the data and applies the task's object poses, for a "scene" recipe it does nothing.

    Raises:
        ValueError: If the recipe has no known form.
    """
    recipe = meta["model"]
    cams = meta["robot_specs"]["CAMERA_SPECS"]
    if "entry" in recipe:
        module_name, function_name = recipe["entry"].split(":")
        return getattr(importlib.import_module(module_name), function_name)(recipe["cfg"], meta)
    if recipe["kind"] == "task":
        from src.task_beaker_hotplate import apply_task_poses, load_task      # only older recordings need the beaker task here
        task_cfg = recipe["task_cfg"]
        sim = load_task(cfg=task_cfg, cameras=cams)

        def reset(model, data):
            mujoco.mj_resetData(model, data)
            apply_task_poses(model, data, task_cfg)
    elif recipe["kind"] == "scene":
        sim = RobotSimulator(model_path=str(PROJECT_ROOT / recipe["scene"]), cameras=cams, pedestal_lift=robot_specs.PEDESTAL_SPECS)
        reset = lambda model, data: None
    else:
        raise ValueError(f"unknown model recipe {recipe!r}")
    return sim.model, sim.data, reset


CONTAINER = {"mp4v": ".mp4", "avc1": ".mp4", "VP90": ".webm", "VP80": ".webm", "MJPG": ".avi", "XVID": ".avi"}   # file extension per fourcc


def open_video(path, fps, size, codec="mp4v", quality=None):
    """Opens an OpenCV video writer.

    Args:
        path (str or pathlib.Path): Output video file.
        fps (float): Frames per second of the video, in sim time.
        size (tuple): (width, height) of the frames in pixels.
        codec (str): Four-character code (fourcc) of the video codec. Defaults to "mp4v".
        quality (int or None): Writer quality from 0 to 100, passed to the writer if not None. Defaults to None (the codec's
            default).

    Returns:
        cv2.VideoWriter: The opened writer.

    Raises:
        RuntimeError: If the writer could not be opened for this codec and path.
    """
    w = cv2.VideoWriter(str(path), cv2.VideoWriter_fourcc(*codec), fps, size)
    if not w.isOpened():
        raise RuntimeError(f"could not open a '{codec}' video writer for {path}")
    if quality is not None:
        w.set(cv2.VIDEOWRITER_PROP_QUALITY, quality)
    return w


class ReplayMismatch(RuntimeError):
    """Raised when the rebuilt model or the replayed initial state differs from the recorded one."""
    pass


class PngFrames:
    """Writes each frame as out/<camera>/<tick:06d>.png (lossless); same write / release interface as a cv2.VideoWriter.

    Attributes:
        folder (pathlib.Path): Folder that receives the Portable Network Graphics (PNG) files. It is created on construction.
    """

    def __init__(self, folder):
        """Creates the output folder.

        Args:
            folder (str or pathlib.Path): Folder for the frames; missing parent folders are created.
        """
        self.folder = Path(folder)
        self.folder.mkdir(parents=True, exist_ok=True)

    def write(self, frame_bgr, tick):
        """Writes one frame as <folder>/<tick:06d>.png.

        Args:
            frame_bgr (numpy.ndarray): Frame as an (height, width, 3) uint8 array in blue-green-red (BGR) channel order.
            tick (int): Control tick the frame was rendered in; it names the file.

        Raises:
            RuntimeError: If the file could not be written.
        """
        if not cv2.imwrite(str(self.folder / f"{tick:06d}.png"), frame_bgr):
            raise RuntimeError(f"could not write a PNG to {self.folder}")

    def release(self):
        """Does nothing; present so PngFrames can stand in for a cv2.VideoWriter."""
        pass


def replay_run(run_dir, out_dir=None, cameras=None, video="preview", hz=30.0, size=None, shadows="policy", codec="mp4v", quality=None,
               verify=True, max_ticks=None, render_ticks=None, quiet=False, name="viewer", after_handoff_s=None, legend_extra=None, face=None):
    """Replays a recorded run: verifies its states and optionally renders its cameras.

    The recording is rebuilt and re-simulated through src/control_loop.run_loop (see the module docstring for what is checked and
    what each video mode writes). The states are verified over the whole run, or up to `max_ticks`, whatever the render range.
    A mismatch of the state after the settle, or of the rebuilt model, raises ReplayMismatch; a mismatch later in the run does not
    raise but is returned in the report.

    Args:
        run_dir (str or pathlib.Path): Recording directory (the one that holds meta.json).
        out_dir (str, pathlib.Path or None): Directory for the videos, frames, frame table and report. Created if missing. Required
            unless `video` is "none". Defaults to None.
        cameras (list of str or None): Names of the cameras to render; None means all recorded cameras. Defaults to None.
        video (str): "none" (verify only), "preview" (one lossy MP4 per camera), "training" (lossless PNG frames per camera) or
            "viewer" (one MP4 of the live viewer's layout). Defaults to "preview".
        hz (float): Rendering rate in frames per second of sim time; it must be a whole divisor of the physics rate, and in "training"
            mode it must not exceed the control tick rate recorded in the metadata. Defaults to 30.0.
        size (tuple or None): (width, height) in pixels that replaces the camera resolution; in "viewer" mode it is the size of the
            whole picture and defaults to (1920, 1080) when None. Defaults to None (the recorded camera resolution).
        shadows (str): "policy" (each camera as recorded), "on" or "off" for all cameras; "viewer" mode always uses "on".
            Defaults to "policy".
        codec (str): OpenCV four-character code (fourcc) of the videos; it also selects the file extension of the "preview" videos
            through CONTAINER. Defaults to "mp4v".
        quality (int or None): Writer quality from 0 to 100, if the codec honours it. Defaults to None (the codec's default).
        verify (bool): Whether to check the states against the recording. If False, `ok` in the report is None. Defaults to True.
        max_ticks (int or None): Stop the replay after this many control ticks; None means the whole recording. Defaults to None.
        render_ticks (tuple or None): (first, last) control tick range, inclusive, in which frames are rendered; None means all
            ticks. Defaults to None.
        quiet (bool): If True, print nothing. Defaults to False.
        name (str): "viewer" mode only: the file stem of the MP4, the handoff PNG, the frame table and the report. Defaults to "viewer".
        after_handoff_s (float or None): Stop the replay (and the video) this many seconds of sim time after the handoff, which is the
            first label of the recording that equals its meta "handoff_label" ("DONE" for older recordings); combined with `max_ticks` by taking the smaller. Defaults to None.
        face (bool or None): Whether the rebuilt model has the robot's head and face (src/face.py), which only the "viewer" video shows (it smiles from the tick
            at which the task's success check first passes, if the recording's recipe names one). None follows FACE_CFG / the --no-face switch. The model hash that
            verifies the replay does not depend on it. Defaults to None.
        legend_extra (list or None): "viewer" mode only: extra (key, label) pairs for the key legend of the status panel; None
            means the keys of the episode viewer for the recorded mode. Defaults to None.

    Returns:
        dict: The report, also written to out_dir/replay_report.json (out_dir/<name>_report.json in "viewer" mode) unless `video` is
        "none". Keys:
            run (str): `run_dir` as a string.
            ok (bool or None): True if every state matched and all `n_ticks` ticks ran, False otherwise; None if `verify` is False.
            ticks (int): Number of control ticks replayed.
            n_ticks_recorded (int): Number of control ticks in the recording.
            mismatch (dict or None): None if nothing differed; otherwise "tick" (int, first control tick whose state hash differs),
                "sim_time" (float, seconds) and, once a checkpoint was reached, "differs" (list of str describing the parts of the
                state that differ).
            warnings (list of str): Non-fatal notes, such as changed robot specifications or a different machine or MuJoCo version.
            videos (dict): Output path (str) per camera name, or under "viewer" the MP4; empty if nothing is rendered.
            frames_rendered (int): Number of frames written per camera.
            wall_seconds (float): Elapsed real time of the call, in seconds.
            handoff_tick (int or None): Control tick of the first handoff label, or None if the recording has none.
            handoff_still (str): "viewer" mode only, present once saved: path of the PNG of the picture at the handoff frame.
            video_bytes (dict): Present if anything was written: size in bytes of each entry of `videos` (the sum of the PNG files
                for a folder).

    Raises:
        ValueError: If `video` is unknown, `out_dir` is missing when needed, a camera is not in the recording, a camera size exceeds
            the offscreen buffer, `hz` is not a whole divisor of the physics rate or exceeds the tick rate in "training" mode, or
            `after_handoff_s` is given for a recording without a handoff, or the recorded model recipe is unknown.
        ReplayMismatch: If the rebuilt model hash or the state after the settle differs from the recording (the latter only when
            `verify` is True).
    """
    wall0 = time.perf_counter()
    rec = load_recording(run_dir)
    meta = rec["meta"]
    labels = meta.get("labels", [])
    handoff_label = meta.get("handoff_label", "DONE")
    handoff_tick = next((l["tick"] for l in labels if l["label"] == handoff_label), None)
    if after_handoff_s is not None:
        if handoff_tick is None:
            raise ValueError("after_handoff_s needs a recording with a handoff (no handoff label in it)")
        end = handoff_tick + int(round(after_handoff_s * meta["source_hz"]))
        max_ticks = end + 1 if max_ticks is None else min(max_ticks, end + 1)
    n_ticks = len(rec["ctrl"]) if max_ticks is None else min(len(rec["ctrl"]), max_ticks)
    report = {"run": str(run_dir), "ok": None, "ticks": 0, "n_ticks_recorded": len(rec["ctrl"]), "mismatch": None, "warnings": [], "videos": {}}

    if specs_snapshot() != meta["robot_specs"]:
        report["warnings"].append("robot_specs differ from the recording's (the model hash below says whether the model changed)")
    previous_face = face_mod.get_override()
    if face is not None:
        face_mod.set_enabled(face)
    try:
        model, data, reset = build_model(meta)
    finally:
        face_mod.set_enabled(previous_face)
    head = face_mod.Face(model)
    smile_check = _load_entry(meta["model"].get("success")) if head.textured and isinstance(meta.get("model"), dict) else None
    if model_hash(model) != meta["model_sha256"]:
        raise ReplayMismatch("the rebuilt model differs from the recorded one (model_sha256): the scene, robot specs or MuJoCo changed")
    if mujoco.__version__ != meta["mujoco"] or meta["machine"] != __import__("platform").machine():
        report["warnings"].append(f"recorded with MuJoCo {meta['mujoco']} on {meta['machine']}; bit-exact replay is not guaranteed here")
    reset(model, data)

    spt = meta["steps_per_tick"]
    physics_hz = 1.0 / model.opt.timestep
    every = physics_hz / hz
    if abs(every - round(every)) > 1e-6:
        raise ValueError(f"camera rate {hz} Hz is not a whole divisor of the physics rate {physics_hz:.0f} Hz")
    every = int(round(every))

    # --- cameras and videos ---
    rig, specs, writers, frames_csv, gl_keepalive = None, [], {}, None, None
    out = Path(out_dir) if out_dir else None
    if video not in ("none", "preview", "training", "viewer"):
        raise ValueError(f"video must be none, preview, training or viewer, not {video!r}")
    composite, still = None, {"path": None, "saved": False}
    if video == "viewer":
        size = tuple(size) if size else (1920, 1080)
        shadows = "on"
        model.vis.global_.offwidth = max(model.vis.global_.offwidth, size[0])      # the offscreen buffer must hold the follow view (before the GL context exists)
        model.vis.global_.offheight = max(model.vis.global_.offheight, size[1])
    if video == "training" and hz > meta["source_hz"] + 1e-9:
        raise ValueError(f"training frames are named by tick: --hz must be at most the tick rate ({meta['source_hz']:g} Hz)")
    if video != "none":
        if out is None:
            raise ValueError(f"video={video!r} needs an out_dir")
        out.mkdir(parents=True, exist_ok=True)
        known = {cs["name"]: cs for cs in meta["robot_specs"]["CAMERA_SPECS"]}
        for cam_name in (cameras if cameras else list(known)):
            if cam_name not in known:
                raise ValueError(f"camera '{cam_name}' not in the recording; has {sorted(known)}")
            cs = dict(known[cam_name])
            if size and video != "viewer":
                cs["resolution"] = tuple(size)
            else:
                cs["resolution"] = tuple(cs["resolution"])
            if shadows != "policy":
                cs["shadows"] = shadows == "on"
            if cs["resolution"][0] > model.vis.global_.offwidth or cs["resolution"][1] > model.vis.global_.offheight:
                raise ValueError(f"{cs['resolution']} is larger than the offscreen buffer "
                                 f"{model.vis.global_.offwidth}x{model.vis.global_.offheight} of the recorded cameras")
            specs.append(cs)
        gl_keepalive, context = _headless_context(model)
        rig = CameraRig(model, specs, context, shadows=bool(meta["loop_cfg"].get("camera_shadows", True)))
        if video == "viewer":
            from src.viewer_composite import CompositeRenderer
            if legend_extra is None:
                legend_extra = ([("F9", "take over"), ("Enter", "hand back")] if meta.get("mode") == "auto" else []) + [("Del", "abort")]
            composite = CompositeRenderer(model, context, specs, size=size, legend_extra=legend_extra)
            path = out / f"{name}.mp4"
            writers["viewer"] = open_video(path, hz, size, codec, quality)
            report["videos"]["viewer"] = str(path)
            still["path"] = out / f"{name}_handoff.png"
        for cs in ([] if video == "viewer" else specs):
            if video == "preview":
                path = out / f"{cs['name']}{CONTAINER.get(codec, '.mp4')}"
                writers[cs["name"]] = open_video(path, hz, tuple(cs["resolution"]), codec, quality)
            else:
                path = out / cs["name"]
                writers[cs["name"]] = PngFrames(path)
            report["videos"][cs["name"]] = str(path)
        frames_csv = open(out / (f"{name}_frames.csv" if video == "viewer" else "frames.csv"), "w", newline="")
        fw = csv.writer(frames_csv)
        fw.writerow(["frame", "tick", "sim_time"])

    # --- verification state ---
    buf = new_state_buffer(model)
    st = {"mismatch": None, "pending": None, "frames": 0, "stop": False}

    def on_start(model_, data_):
        """Compares the state after the settle with the recorded one.

        Passed to run_loop as cfg["replay"]["on_start"]; run_loop calls it once, after the settle and before the first tick.
        It reads the enclosing `verify`, `rec` and `buf`, and overwrites `buf` with the current state.

        Args:
            model_ (mujoco.MjModel): The model being replayed.
            data_ (mujoco.MjData): Its data, after the settle.

        Raises:
            ReplayMismatch: If `verify` is True and the state differs from the recorded initial state.
        """
        get_state(model_, data_, buf)
        if verify and not np.array_equal(buf, rec["initial_state"]):
            raise ReplayMismatch("the state after the settle differs from the live run's: " + "; ".join(describe_state_diff(model_, buf, rec["initial_state"])))

    phase_at = np.empty(len(rec["ctrl"]), dtype=object)
    for i, l in enumerate(labels):
        phase_at[l["tick"]:(labels[i + 1]["tick"] if i + 1 < len(labels) else len(phase_at))] = l["label"]
    tick_dt = spt * model.opt.timestep

    def composite_info(tick, data_):
        """Builds what the live viewer's status panel would show at a tick, from the recording.

        It reads the enclosing `rec` (the recorded base velocity), `phase_at` (the phase label per tick), `handoff_tick`,
        `tick_dt`, `meta` and `hz`; it changes nothing.

        Args:
            tick (int): Control tick, counted from 0.
            data_ (mujoco.MjData): Data at the state of that tick; its time and base orientation are used.

        Returns:
            dict: Information for CompositeRenderer.render with the keys "time" (float, sim time in seconds), "base_vel" (tuple of
            the recorded world-frame base velocity vx, vy in metres per second and wz in radians per second), "twist" (tuple of
            forward speed in metres per second and yaw rate in radians per second, from the base velocity rotated into the
            base frame), "status" (str, the phase label, followed by the whole seconds since the handoff once it has happened),
            "mode" ("teleop" for the recorded phase "OPERATOR", "auto" for other phases, or None unless the recording's mode is
            "auto") and "fps" (float, the rendering rate `hz`).
        """
        vx, vy, wz = (float(v) for v in rec["basevel"][tick])
        yaw = base_yaw(data_)
        phase = phase_at[tick] or "DRIVE"
        status = phase + (f"  (+{(tick - handoff_tick) * tick_dt:.0f} s)" if handoff_tick is not None and tick >= handoff_tick else "")
        return {"time": data_.time, "base_vel": (vx, vy, wz), "twist": (vx * math.cos(yaw) + vy * math.sin(yaw), wz), "status": status,
                "mode": ("teleop" if phase == "OPERATOR" else "auto") if meta.get("mode") == "auto" else None, "fps": hz}

    def on_step(step_count, data_):
        """Renders and writes the frames of one physics step, when this step is a rendering step.

        Passed to run_loop as cfg["replay"]["on_step"]; run_loop calls it after every physics step. A frame is rendered when
        `step_count` is a multiple of `every` and its control tick, (step_count - 1) // spt, lies in `render_ticks`. In "viewer"
        mode (`composite` is set) the composite picture goes to writers["viewer"], and the first picture at or after the handoff
        tick is also saved as a PNG (the enclosing `still` and report["handoff_still"] are set). Otherwise, when a camera rig
        exists, every selected camera image goes to its writer (with the tick as well in "training" mode). In both cases a row
        is added to the frame table (`fw`) and st["frames"] is incremented. Nothing is done in "none" mode.

        Args:
            step_count (int): Number of physics steps taken so far in the run, including this one.
            data_ (mujoco.MjData): Data after this step.
        """
        if composite is not None and step_count % every == 0 and (render_ticks is None or render_ticks[0] <= (step_count - 1) // spt <= render_ticks[1]):
            tick = (step_count - 1) // spt
            bgr = cv2.cvtColor(composite.render(data_, composite_info(tick, data_)), cv2.COLOR_RGB2BGR)
            writers["viewer"].write(bgr)
            if not still["saved"] and handoff_tick is not None and tick >= handoff_tick:        # the picture at the handoff frame
                cv2.imwrite(str(still["path"]), bgr)
                still["saved"] = True
                report["handoff_still"] = str(still["path"])
            fw.writerow([st["frames"], tick, f"{data_.time:.6f}"])
            st["frames"] += 1
        elif rig is not None and composite is None and step_count % every == 0 and (render_ticks is None or render_ticks[0] <= (step_count - 1) // spt <= render_ticks[1]):
            rig.render(data_)
            tick = (step_count - 1) // spt
            for cs in specs:
                bgr = cv2.cvtColor(rig.images[cs["name"]], cv2.COLOR_RGB2BGR)
                writers[cs["name"]].write(bgr, tick) if video == "training" else writers[cs["name"]].write(bgr)
            fw.writerow([st["frames"], tick, f"{data_.time:.6f}"])
            st["frames"] += 1

    def on_tick_end(frame, data_):
        """Checks the state hash after a control tick against the recording.

        Passed to run_loop as cfg["replay"]["on_tick_end"]. Does nothing if `verify` is False. On the first hash mismatch it records
        st["mismatch"] with the tick and sim time. If that tick is a recorded checkpoint it also records which parts of the state
        differ and sets st["stop"] so the replay ends; otherwise it sets st["pending"] and does the same at the next checkpoint
        tick, prefixing each description with that tick.

        Args:
            frame (int): The control tick that just finished, counted from 0.
            data_ (mujoco.MjData): Data after that tick's physics steps.
        """
        if smile_check is not None and not head.smiling and (handoff_tick is None or frame >= handoff_tick) and smile_check(model, data_)[0]:
            head.set_smile(True)                                     # as the live episode did, on the tick the success check first passed
        if not verify:
            return
        get_state(model, data_, buf)
        if st["mismatch"] is None and state_hash(buf) != int(rec["hashes"][frame]):
            st["mismatch"] = {"tick": frame, "sim_time": data_.time}
            if frame in rec["checkpoints"]:
                st["mismatch"]["differs"] = describe_state_diff(model, buf, rec["checkpoints"][frame])
                st["stop"] = True
            else:
                st["pending"] = True
        elif st["pending"] and frame in rec["checkpoints"]:
            st["mismatch"]["differs"] = [f"at checkpoint tick {frame}: " + s for s in describe_state_diff(model, buf, rec["checkpoints"][frame])]
            st["stop"] = True

    cfg = {**meta["loop_cfg"], "cameras": False, "inset_cameras": False, "record_run": None, "mode": "teleop", "auto_source": None, "on_tick": None, "held": None, "tick_ref": None,
           "bench_frames": 0, "bench_log": None, "hotkeys": {}, "routes": {},
           "replay": {"ctrl": rec["ctrl"], "basevel": rec["basevel"], "gripforce": rec["gripforce"], "n_ticks": n_ticks, "on_start": on_start, "on_step": on_step,
                      "on_tick_end": on_tick_end, "stop": lambda: st["stop"]}}
    cfg["claimed_ids"] = list(cfg.get("claimed_ids") or ())
    try:
        result = run_loop(model, data, {}, cfg, viewer=None)
    finally:
        for w in writers.values():
            w.release()
        if frames_csv is not None:
            frames_csv.close()
        if gl_keepalive is not None:
            try:
                gl_keepalive.free()
            except Exception:
                pass

    report["ticks"] = result["frames"]
    report["mismatch"] = st["mismatch"]
    report["frames_rendered"] = st["frames"]
    report["ok"] = (st["mismatch"] is None and result["frames"] == n_ticks) if verify else None
    report["wall_seconds"] = time.perf_counter() - wall0
    report["handoff_tick"] = handoff_tick
    if writers:
        report["video_bytes"] = {k: (sum(f.stat().st_size for f in Path(v).glob("*.png")) if Path(v).is_dir() else Path(v).stat().st_size)
                                 for k, v in report["videos"].items() if Path(v).exists()}
    if video != "none":
        (out / (f"{name}_report.json" if video == "viewer" else "replay_report.json")).write_text(json.dumps(jsonable(report), indent=1))
    if not quiet:
        if verify:
            print(("VERIFIED: " + f"{report['ticks']} ticks ({report['ticks'] / meta['source_hz']:.1f} s sim), every state bit-identical to the live run")
                  if report["ok"] else f"MISMATCH: {report['mismatch']}")
        for w in report["warnings"]:
            print("warning:", w)
        if writers:
            print(f"{video}: rendered {st['frames']} frames per camera at {hz:g} Hz: " + ", ".join(f"{k} {v / 1e6:.1f} MB" for k, v in report["video_bytes"].items())
                  + f"  ({report['wall_seconds']:.0f} s wall)")
    return report
